258	     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
259	     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
260	     * and stored so it is reported consistently on every later read.
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
